mod tests {
    use super::*;
    use crate::hir::funded::payer::{assert_every_boundary, Payer};

    const SOURCE: &str = r#"module concat.funded;
@id("c.main") fn main()->i64 {
 let mut text=string_from_i64(1);
 let mut count=0;
 while count<3 {
