        };
        let owners = statements.iter().filter_map(|s| match s {
            ResolvedStatement::Let { binding, .. } => Some(binding.id.clone()),
            _ => None,
        });
        let mut checked = 0;
        for owner in owners {
            let mut payer = Payer::unlimited();
            let needle = needle(&owner, &mut |b| payer.pay(b)).unwrap();
